// Settings for the tools, from a file next to the sources or from the command line.
//
// A file is either a list of `key = value` lines (`#` and `;` start a comment line), or a JSON object whose values are
// strings, numbers or booleans. Both can be in either file name, the first character tells them apart. Keys are not case
// sensitive and `-` is the same as `_`.
#pragma once
#include <filesystem>
#include <map>
#include <optional>
#include <string>
#include <vector>

namespace blitz::tools {
	using settings = std::vector<std::pair<std::string, std::string>>; // In the order they were written

	/** The nearest of the files in the directory or in one of its parents. In every directory the names are tried in the
	 * order they are given.
	 */
	std::optional<std::filesystem::path> find_config(std::filesystem::path directory, std::vector<std::string> const& names);

	/** Read the settings out of a file. Throws std::runtime_error with the file and line on a malformed file.
	 */
	settings load_config(std::filesystem::path const& file);

	/** Parse the text of a configuration file. The name is only used for error messages.
	 */
	settings parse_config(std::string const& text, std::string const& name);

	/** The key as the tools compare it: lower case, with _ for -.
	 */
	std::string normalize_key(std::string key);
} // namespace blitz::tools
